export function getModuleMap(
  modulePackageNames: string[],
): { [key: string]: string } {
  const map: { [key: string]: string } = {}
  modulePackageNames.forEach((packageName) => {
    const moduleGlobalVariable = getModuleGlobalVariableName(packageName)
    const moduleKey = moduleGlobalVariable.split('_')[1]
    map[moduleKey] = moduleGlobalVariable
  })
  return map
}

export function getWebviewRelayModules(
  modulePackageNames: string[],
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
): { [key: string]: any } {
  const moduleMap = getModuleMap(modulePackageNames)
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const moduleMapResolved: { [key: string]: any } = {}
  Object.keys(moduleMap).forEach((key) => {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    moduleMapResolved[key] = (globalThis as any)[moduleMap[key]]
  })
  return moduleMapResolved
}

export function makeComlinkProxy<T>(obj: T): T {
  return Comlink.proxy(obj)
}
