import { Comlink } from './comlink'
import { EndpointFactory, generateUUID } from './endpoint'
import type { ForeignImports, ForeignExports } from './endpoint'

const DEBUG = false

const EXPORTS = 'FlowPub_Core_WebviewRelay_exports'
const IMPORTS = 'FlowPub_Core_WebviewRelay_imports'

declare global {
  // eslint-disable-next-line no-var
  var FlowPub_Core_WebviewRelay_exports: ForeignExports
  // eslint-disable-next-line no-var
  var FlowPub_Core_WebviewRelay_imports: ForeignImports

  interface UserMessageHandler {
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    postMessage(message: any): void
  }

  interface UserMessageHandlersNamespace {
    [name: string]: UserMessageHandler
  }

  interface WebKitNamespace {
    messageHandlers: UserMessageHandlersNamespace
  }

  // eslint-disable-next-line no-var
  var webkit: WebKitNamespace
}

export class WebviewRelay {
  private _endpointFactory: EndpointFactory

  constructor() {
    globalThis[EXPORTS] = {} as ForeignExports

    if (typeof globalThis[IMPORTS] === 'undefined') {
      globalThis[IMPORTS] = {
        postMessageWithOptionalPort: function (
          json: string,
          portId: string | null = null,
        ): void {
          globalThis.webkit.messageHandlers.flowpubSDK.postMessage({
            json,
            portId,
          })
        },
      }
    }

    this._endpointFactory = new EndpointFactory(
      globalThis[IMPORTS],
      globalThis[EXPORTS],
    )

    Comlink.transferHandlers.set('proxy', {
      canHandle: (obj) => obj && obj[Comlink.proxyMarker],
      // eslint-disable-next-line @typescript-eslint/no-explicit-any
      serialize: (obj: any): [any, Transferable[]] => {
        // eslint-disable-next-line no-console
        DEBUG && console.log('proxy:serialize', obj)
        const port = generateUUID()
        Comlink.expose(obj, this._endpointFactory.create(port))
        return [{ id: port }, []]
      },
      deserialize: (handler) => {
        // eslint-disable-next-line no-console
        DEBUG && console.log('proxy:deserialize', handler.id)
        return Comlink.wrap(this._endpointFactory.create(handler.id))
      },
    })
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  public expose(value: any): void {
    Comlink.expose(value, this._endpointFactory.create())
  }
}

export function exposeWebviewRelayModules(moduleMapResolved: {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  [key: string]: any
}): void {
  new WebviewRelay().expose(moduleMapResolved)
}
