import { convertHeadersToTransferable } from './headers-to-transferable'
import type {
  HeadersTransferrable,
  RequestTransferable,
  RequestDuplex,
} from './types'

/**
 * Copy the original request's field values into a plain object.
 * The plain object can be easily transferred between browser threads.
 * There are limitations on accessing the request fields imposed by the browser
 * depending on the request type.
 *
 * WARNING! Not all the headers can be copied due to browser restrictions.
 * Even though simple "Range" header is allowed in a cors and non-cors request
 * the access to it is not permitted at least in Chrome. So this header won't
 * be copied.
 *
 * WARNING! There are many limitation on CORS requests.
 * Thus, this function should be utilized with caution.
 * In some cases there is no access to all properties of the original request
 * and the copy won't be an exact match of the original request.
 * Not all headers keys can be set on CORS request, hence even having ability
 * to read original request headers doesn't mean that they will be copied
 * and appear in a copy.
 *
 * Since ServiceWorker doesn't intercept a preflight requests, its not necessary
 * to support them in the function.
 * https://github.com/w3c/ServiceWorker/issues/1610.
 *
 * @export
 * @param {Request} request - an instance of Request.
 * @return {RequestTransferable} - a plain JS object mirrored from the given request.
 */
export async function convertRequestToTransferable(
  request: Request,
): Promise<RequestTransferable> {
  const requestCloned: Request = request.clone()

  let requestBody: ArrayBuffer | undefined
  if (requestCloned.body) {
    // TODO - #143476 turn on the conversion only in Safari.
    // In the rest of browsers the body should be transferred
    // as a ReadableStream.
    requestBody = await new Response(requestCloned.body).arrayBuffer() // this way it won't throw an exception that the request has already been read
  }

  const {
    bodyUsed,
    cache,
    credentials,
    destination,
    headers,
    integrity,
    keepalive,
    method,
    mode,
    redirect,
    referrer,
    referrerPolicy,
    url,
  } = requestCloned

  const headersCloned: HeadersTransferrable = convertHeadersToTransferable(
    headers,
  )

  // TODO - Typescript error
  // is missing the following properties from type 'RequestTransferable': isHistoryNavigation, isReloadNavigation
  const requestTransferrable: Omit<
    RequestTransferable,
    'isHistoryNavigation' | 'isReloadNavigation'
  > = {
    // There are limitations on headers that can be accessed(read and cloned)
    // due to CORS policy
    // https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS#simple_requests
    // https://fetch.spec.whatwg.org/#cors-safelisted-request-header
    // https://developer.okta.com/blog/2021/08/02/fix-common-problems-cors#what-else-does-cors-block
    // https://web.dev/introduction-to-fetch/#response-types
    headers: headersCloned,
    bodyUsed,
    body: requestBody,
    cache,
    credentials,
    destination,
    integrity,
    keepalive,
    method,
    mode,
    redirect,
    referrer,
    referrerPolicy,
    url,
    // https://developer.chrome.com/articles/fetch-streaming-requests/#feature-detection
    duplex: (requestCloned as RequestDuplex).duplex ?? undefined,
  }

  // TODO - it seems to be a browser dependent
  if ((request as any).isHistoryNavigation !== undefined) {
    ;(requestTransferrable as any).isHistoryNavigation = (request as any).isHistoryNavigation
  }
  // TODO - it seems to be a browser dependent
  if ((request as any).isReloadNavigation !== undefined) {
    ;(requestTransferrable as any).isReloadNavigation = (request as any).isReloadNavigation
  }

  // TODO - see Typescript error "isHistoryNavigation", "isReloadNavigation" above
  return requestTransferrable as RequestTransferable
}
