import type { RequestDuplex, RequestTransferable } from './types'
import { convertHeadersFromTransferable } from './headers-from-transferable'

/**
 * Convert a plain object with properties matching the Request interface
 * into an instance of Request.
 *
 * WARNING! If request is made from ReadableStream, mode should be"same-origin" or "cors".
 *
 * WARNING! Requests having the "keepalive" set to true can not have a body.
 *
 * WARNING! Request methods "TRACE", "CONNECT" can not be set from JS code.
 *
 * WARNING! Request methods "PUT", "DELETE", "PATCH", "OPTIONS" are not supported
 * in the "no-cors" mode.
 *
 * WARNING! Cache mode value 'only-if-cached' can be set only with 'same-origin' mode.
 *
 * WARNING! There is no way to instantiate a request with modes "navigate" and "websocket"
 * JS code. Only the browser itself can do that.
 * https://developer.mozilla.org/en-US/docs/Web/API/Request/mode
 * "navigate
 * A mode for supporting navigation. The navigate value is intended to be used only by HTML navigation. A navigate request is created only while navigating between documents.
 * websocket
 * A special mode used only when establishing a WebSocket connection."
 *
 * WARNING! There is no way to set request "priority" attribute from JS code.
 * https://html.spec.whatwg.org/multipage/urls-and-fetching.html#fetch-priority-attributes.
 * https://github.com/WICG/priority-hints/blob/main/EXPLAINER.md.
 *
 * WARNING! In case of CORS request it's impossible to set certain headers
 * on a Request instance. Even though some header exist in the
 * "requestTransferableObject" their presence in the resulted Request depends
 * on the request type.
 * https://developer.mozilla.org/en-US/docs/Web/API/Request/Request:
 * "A Request object, effectively creating a copy. Note the following behavioral updates to retain security while making the constructor less likely to throw exceptions:
 * If this object exists on another origin to the constructor call, the Request.referrer is stripped out.
 * If this object has a Request.mode of navigate, the mode value is converted to same-origin."
 *
 * @export
 * @param {RequestTransferable} requestTransferableObject - key-value pairs carrying information on the Request instance.
 * @return {Request}
 */
export function convertRequestFromTransferable(
  requestTransferableObject: RequestTransferable,
): Request {
  const { url, headers: headersTransferableObject } = requestTransferableObject
  const headers: Headers = convertHeadersFromTransferable(
    headersTransferableObject ?? {},
  )
  const request: Request = new Request(url, {
    ...requestTransferableObject,
    // https://developer.mozilla.org/en-US/docs/Web/API/Request/mode
    // If `request.mode` === 'cors'.
    // https://developer.mozilla.org/en-US/docs/Glossary/Forbidden_header_name
    // Some headers(e.g. 'sec-ch-ua', 'user-agent', 'dht) will be omitted
    // by the Request constructor.
    // Thus, they won't be presented in the `request.headers` object.
    //
    // If `request.mode` === 'no-cors', then only Simple Headers can be copied.
    // https://developer.mozilla.org/en-US/docs/Glossary/CORS-safelisted_request_header
    headers,
    /**
     * Uncaught TypeError: Failed to construct 'Request': The `duplex` member must be specified for a request with a streaming body
     * https://github.com/whatwg/fetch/issues/1486
     * */
    duplex: requestTransferableObject.duplex ?? 'half',
  } as RequestInit & RequestDuplex)

  Object.defineProperty(request, 'bodyUsed', {
    configurable: false,
    enumerable: true,
    get() {
      return requestTransferableObject.bodyUsed
    },
  })

  // TODO - it seems to be a browser dependent
  Object.defineProperty(request, 'isHistoryNavigation', {
    configurable: false,
    enumerable: true,
    get() {
      return (requestTransferableObject as any).isHistoryNavigation
    },
  })

  // TODO - it seems to be a browser dependent
  Object.defineProperty(request, 'isReloadNavigation', {
    configurable: false,
    enumerable: true,
    get() {
      return (requestTransferableObject as any).isReloadNavigation
    },
  })

  return request
}
