import type { HeadersTransferrable } from './types'

/**
 * Converts headers instance into a key-value pairs.
 *
 * WARNING! There are some restrictions on accessing
 * original headers imposed by the browser in case of
 * CORS policies.
 *
 * @export
 * @param {Headers} headers
 * @return {HeadersTransferrable}
 */
export function convertHeadersToTransferable(
  headers: Headers,
): HeadersTransferrable {
  const headersObjectTransferrable: HeadersTransferrable = {}
  headers.forEach((headerValue: string, headerName: string) => {
    headersObjectTransferrable[headerName] = headerValue
  })
  return headersObjectTransferrable
}
