import type { HeadersTransferrable } from './types'

/**
 * Converts a plain object with headers as values
 * into a Headers instance.
 *
 * @export
 * @param {HeadersTransferrable} headersTransferrable - a plain object containing key-value pairs.
 * @return {Headers}
 */
export function convertHeadersFromTransferable(
  headersTransferrable: HeadersTransferrable,
): Headers {
  const headers: Headers = new Headers(headersTransferrable)
  return headers
}
