import EventTarget from '@ungap/event-target'

const DEBUG = false

/**
 * Custom `MessagePort` shim for receiving and sending messages.
 *
 * IMPORTANT: This class name needs to stay as `MessagePort`
 * because [Comlink expects it as such](https://git.io/Jewam).
 */
class MessagePort {
  private _context: EndpointFactory
  private _portId: string | null
  private _eventTarget: EventTarget

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  public addEventListener: any
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  public removeEventListener: any

  constructor(portId: string | null, context: EndpointFactory) {
    this._context = context
    this._portId = portId
    this._eventTarget = context.generalTarget
    if (portId) {
      this._eventTarget = new EventTarget()
      context.portTargets[portId] = this._eventTarget
    }

    this.addEventListener = this._eventTarget.addEventListener.bind(
      this._eventTarget,
    )
    this.removeEventListener = this._eventTarget.removeEventListener.bind(
      this._eventTarget,
    )
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  public postMessage(message: any): void {
    // eslint-disable-next-line no-console
    DEBUG && console.log('MessagePort', 'postMessage', this._portId, message)

    this._context.postMessageWithOptionalPort(message, this._portId)
  }

  public close(): void {
    // eslint-disable-next-line no-console
    DEBUG && console.log('MessagePort', 'close')
  }
}

export interface ForeignImports {
  postMessageWithOptionalPort(json: string, portId: string | null): void
}

export interface ForeignExports {
  postMessageWithOptionalPort(json: string, portId: string | null): void
  destroyEndpoint(portId: string): void
}

export class EndpointFactory {
  public generalTarget: EventTarget = new EventTarget()

  public portTargets: { [portId: string]: EventTarget } = {}

  public postMessageWithOptionalPort: (
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    message: any,
    portId: string | null,
  ) => void

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  constructor(foreignImports: ForeignImports, foreignExports: ForeignExports) {
    const { postMessageWithOptionalPort } = foreignImports

    this.postMessageWithOptionalPort = (message, portId = null): void => {
      const json = JSON.stringify(message, (_k, v) =>
        v === undefined ? null : v,
      )
      postMessageWithOptionalPort.call(foreignImports, json, portId)
    }

    foreignExports.postMessageWithOptionalPort = (
      json: string,
      portId: string | null = null,
    ): void => {
      DEBUG &&
        // eslint-disable-next-line no-console
        console.log(
          'EndpointContext',
          'postMessageWithOptionalPort',
          portId,
          json,
        )

      let target = this.generalTarget

      if (portId) {
        target = this.portTargets[portId]
      }

      target.dispatchEvent(
        new MessageEvent('message', {
          data: json,
        }),
      )
    }

    foreignExports.destroyEndpoint = (portId: string): void => {
      this.destroy(portId)
    }
  }

  public create(portId: string | null = null): MessagePort {
    return new MessagePort(portId, this)
  }

  public exists(portId: string): boolean {
    return !!this.portTargets[portId]
  }

  public destroy(portId: string): void {
    const target = this.portTargets[portId]
    if (target) {
      delete this.portTargets[portId]
    }
  }
}

export function generateUUID(): string {
  return new Array(4)
    .fill(0)
    .map(() => Math.floor(Math.random() * Number.MAX_SAFE_INTEGER).toString(16))
    .join('-')
}
