/**
 * Converts a string in `kebab-case` to `camelCase`.
 * @param {String} input Input string in kebab case.
 */
export function kebabCaseToCamelCase(input: string): string {
  const words = input.split('-')
  return words.reduce(
    (previous, current) =>
      previous + current.charAt(0).toUpperCase() + current.substring(1),
  )
}

/**
 * Transforms a package identifier:
 *   `@flowpub/some-package-name`
 *
 * Into a global variable identifier:
 *   `flowpub_somePackageName`
 * @param {String} modulePackageName The `package.json` name field for the module.
 */
export function getModuleGlobalVariableName(modulePackageName: string): string {
  const [packageScope, packageName] = modulePackageName.split('/')
  const prefix = kebabCaseToCamelCase(packageScope.substring(1))
  const suffix = kebabCaseToCamelCase(packageName)
  return `${prefix}_${suffix}`
}

/**
 * Creates an instance of Response and copies the url
 * address if it's defined in the "init" parameter.
 *
 * @export
 * @param {(BodyInit | null)} [body]
 * @param {ResponseInit & Partial<{ url: string, bodyUsed: boolean }>} [init]
 * @return {Response}
 */
export function createResponseInstance(
  body?: BodyInit | null,
  init?: ResponseInit & Partial<{ url: string; bodyUsed: boolean }>,
  ResponseConstructor: typeof Response = Response,
): Response {
  const response = new ResponseConstructor(body, init)

  const urlOrUndefined: string | undefined = init?.url
  if (urlOrUndefined) {
    // https://stackoverflow.com/a/57382543
    Object.defineProperty(response, 'url', {
      configurable: false,
      enumerable: true,
      get() {
        return urlOrUndefined
      },
    })
  }

  const bodyUsedOrUndefined: boolean | undefined = init?.bodyUsed
  if (typeof bodyUsedOrUndefined === 'boolean') {
    Object.defineProperty(response, 'bodyUsed', {
      configurable: false,
      enumerable: true,
      get() {
        return bodyUsedOrUndefined
      },
    })
  }
  return response
}
