import { createResponseInstance } from '../util'

import { convertHeadersFromTransferable } from './headers-from-transferable'
import { ResponseTransferable } from './types'

/**
 * Convert a plain object with properties matching the Response interface
 * into an instance of Response.
 *
 * WARNING! Only the response status in a range from 200 to 599 are allowed.
 *
 * WARNING! In case of CORS response it's impossible to set a body on a certain
 * response type (opaque response).
 * https://whatwebcando.today/articles/opaque-responses-service-worker/
 *
 * WARNING! In case of CORS response it's impossible to set certain headers
 * on a Response instance. Even though some header exist in the
 * "responseTransferrableObject" their presence in the resulted Response instance
 * depends on the response type.
 * https://web.dev/introduction-to-fetch/#response-types/
 *
 *
 * @export
 * @param {ResponseTransferable} responseTransferrableObject - key-value pairs carrying information on the Response instance.
 * @return {Response}
 */
export function convertResponseFromTransferable(
  responseTransferrableObject: ResponseTransferable,
): Response {
  const {
    body,
    headers: headersTransferableObject,
  } = responseTransferrableObject
  const headers: Headers = convertHeadersFromTransferable(
    headersTransferableObject ?? {},
  )
  const response: Response = createResponseInstance(body, {
    ...responseTransferrableObject,
    // https://developer.mozilla.org/en-US/docs/Glossary/Forbidden_response_header_name
    headers,
  })

  return response
}
