// type RequestMode
export enum RequestModeValue {
  CORS = 'cors',
  // can not be set from JS code.
  Navigate = 'navigate',
  NoCORS = 'no-cors',
  SameOrigin = 'same-origin',
  // can not be set from JS code.
  WebSocket = 'websocket',
}

// type RequestCredentials
export enum RequestCredentialsValue {
  Omit = 'omit',
  SameOrigin = 'same-origin',
  Include = 'include',
}

// https://developer.mozilla.org/en-US/docs/Web/HTTP/Methods
export enum RequestMethodValue {
  Get = 'GET',
  Post = 'POST',
  Head = 'HEAD',
  Put = 'PUT',
  Delete = 'DELETE',
  Connect = 'CONNECT',
  Options = 'OPTIONS',
  Trace = 'TRACE',
  Patch = 'PATCH',
}

// type RequestCache
export enum RequestCacheValue {
  Default = 'default',
  ForceCache = 'force-cache',
  NoCache = 'no-cache',
  NoStore = 'no-store',
  OnlyIfCached = 'only-if-cached',
  Reload = 'reload',
}

// type RequestRedirect
export enum RequestRedirectValue {
  Error = 'error',
  Follow = 'follow',
  Manual = 'manual',
}

export enum RequestReferrerValue {
  NoReferrer = 'no-referrer',
  Client = 'client',
  // another possible value is an url
}

// type ReferrerPolicy
export enum ReferrerPolicyValue {
  Empty = '',
  NoReferrer = 'no-referrer',
  NoReferrerWhenDowngrade = 'no-referrer-when-downgrade',
  Origin = 'origin',
  OriginWhenCrossOrigin = 'origin-when-cross-origin',
  SameOrigin = 'same-origin',
  StrictOrigin = 'strict-origin',
  StrictOriginWhenCrossOrigin = 'strict-origin-when-cross-origin',
  UnsafeUrl = 'unsafe-url',
}

// should be a boolean
export enum RequestKeepaliveValue {
  Persistent = 'true',
  OneTime = 'false',
}
