import { convertHeadersToTransferable } from './headers-to-transferable'
import type { ResponseTransferable, HeadersTransferrable } from './types'

/**
 * Copy the original response's field values into a plain object.
 * The plain object can be easily transferred between browser threads.
 * There are limitations on accessing the response fields imposed by the browser
 * depending on the response type.
 * https://web.dev/introduction-to-fetch/#response-types/
 * https://whatwebcando.today/articles/opaque-responses-service-worker/
 *
 * WARNING! There are many limitation on CORS responses.
 * Thus, this function should be utilized with caution.
 * In some cases there is no access to all properties of the original response
 * and the copy won't be an exact match of the original request.
 * Not all headers keys can be set on CORS response, hence even having ability
 * to read original request headers doesn't mean that they will be copied
 * and appear in a copy.
 *
 * WARNING! Responses to requests sent along with the credentials have limitations.
 * https://developer.mozilla.org/en-US/docs/Web/HTTP/CORS#requests_with_credentials:
 * "If a request includes a credential (most commonly a Cookie header) and the response includes an Access-Control-Allow-Origin: * header (that is, with the wildcard), the browser will block access to the response, and report a CORS error in the devtools console."
 *
 * WARNING! There are plenty of limitations on dealing with an opaque response.
 * It's better not to use this function to make their copies in order to transfer
 * them to another thread, but rather pass them down to the request initiator as is.
 * https://stackoverflow.com/a/36294173.
 * https://tpiros.dev/blog/what-is-an-opaque-response/
 *
 * @export
 * @param {Response} response - an instance of Response interface.
 * @return {ResponseTransferable} -a plain JS object mirrored from the given response
 */
export async function convertResponseToTransferable(
  response: Response,
): Promise<ResponseTransferable> {
  const {
    bodyUsed,
    redirected,
    status,
    statusText,
    url,
    headers,
    ok,
    type,
  } = response

  // Restrictions on headers are also dictated by response type.
  // https://web.dev/introduction-to-fetch/#response-types
  // Quotes from the resource:
  // "If a request is made for a resource on another origin which returns the CORs headers, then the type is cors. cors and basic responses are almost identical except that a cors response restricts the headers you can view to Cache-Control, Content-Language, Content-Type, Expires, Last-Modified, and Pragma."
  // "An opaque response is for a request made for a resource on a different origin that doesn't return CORS headers. With an opaque response we won't be able to read the data returned or view the status of the request, meaning we can't check if the request was successful or not."

  // https://developer.mozilla.org/en-US/docs/Glossary/CORS-safelisted_response_header
  // in case of CORS not all the headers can be accessed
  // https://stackoverflow.com/questions/37897523/axios-get-access-to-response-header-fields
  // https://developer.okta.com/blog/2021/08/02/fix-common-problems-cors#restrictions-on-response-headers
  // https://developer.okta.com/blog/2021/08/02/fix-common-problems-cors#credentials-are-a-special-case
  const headersCloned: HeadersTransferrable = convertHeadersToTransferable(
    headers,
  )

  // TODO - #143476 turn on the conversion only in Safari.
  // In the rest of browsers the body should be transferred
  // as a ReadableStream.
  const responseCloned = response.clone()
  const bodyArrayBuffer = await new Response(responseCloned.body).arrayBuffer()

  const responseTransferrable: ResponseTransferable = {
    headers: headersCloned,
    bodyUsed,
    body: bodyArrayBuffer,
    redirected,
    status,
    statusText,
    url,
    ok,
    type,
  }

  return responseTransferrable
}
